"use server";

import type {
  MetricsActionResult,
  MetricsFilters,
  MetricsReport,
} from "@/components/sendo/metrics/types";
import { fixtureReport, metricsFixture } from "@/fixtures/metrics";

// Dev-only stand-in for app/(protected)/inbox/metrics/actions.ts: same result shape, rows
// generated by the fixture and folded by the item's own `summarizeMetrics`.

export async function loadFixtureMetrics(
  data: string,
  filters: MetricsFilters,
): Promise<MetricsActionResult<MetricsReport>> {
  if (process.env.NODE_ENV === "production") {
    return { ok: false, code: "FORBIDDEN", message: "Dev only" };
  }
  const { key } = metricsFixture(data);
  // A short wait so the "keeps the frame" refetch state is visible.
  await new Promise((resolve) => setTimeout(resolve, 350));
  return { ok: true, data: fixtureReport(key, filters) };
}
